const res = $json;
const text = res.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('').trim();
if (!text) { throw new Error('Gemini did not return post text: ' + JSON.stringify(res)); }
return [{ json: { post_text: text } }];

const idea = $('Get Idea Rows').first().json.idea;
const postText = $input.first().json.post_text;
const prompt = 'Create a clean, modern, professional illustration (16:9) suitable as a LinkedIn post '
  + 'image for this topic: "' + idea + 'content:' +  postText + '".\n'
  + 'Style: minimal, flat vector illustration, soft corporate colour palette, '
  + 'no text overlays, no logos, no watermarks.';
return [{ json: { image_prompt: prompt } }];

const res = $json;
const parts = res.candidates?.[0]?.content?.parts || [];
const imgPart = parts.find(p => p.inlineData || p.inline_data);
const inline = imgPart ? (imgPart.inlineData || imgPart.inline_data) : null;
if (!inline) { throw new Error('Gemini did not return image data: ' + JSON.stringify(res)); }
return [{ json: { image_base64: inline.data, mime_type: inline.mimeType || inline.mime_type || 'image/png' } }];

const cq = $json.callback_query;
const parts = (cq.data || '').split('|');
return [{ json: {
  action: parts[0],
  post_id: parts[1],
  chat_id: cq.message.chat.id,
  message_id: cq.message.message_id,
  callback_query_id: cq.id,
  original_caption: cq.message.caption || ''
} }];

const target = $('Extract Incoming Message').first().json;
const rows = $input.all();
const match = rows.find(r => String(r.json.telegram_chat_id) === String(target.chat_id)
  && ['awaiting_edit_content', 'awaiting_edit_image'].includes(r.json.status));
if (!match) { return [{ json: { found: false, chat_id: target.chat_id } }]; }
return [{ json: { found: true, ...match.json, incoming_text: target.incoming_text, chat_id: target.chat_id } }];

const idea = $json.idea;
const currentText = $json.post_text;
const change = $json.incoming_text;
const prompt = 'Here is the current LinkedIn post draft:\n"""' + currentText + '"""\n\n'
  + 'The original idea/topic was: "' + idea + '"\n\n'
  + 'The user wants this change applied: "' + change + '"\n\n'
  + 'Rewrite the LinkedIn post applying that change, keeping the rest of the good parts intact. '
  + 'Return ONLY the updated post text, no preamble, no quotation marks, no markdown.';
return [{ json: { text_prompt: prompt } }];

const res = $json;
const text = res.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('').trim();
if (!text) { throw new Error('Gemini did not return post text: ' + JSON.stringify(res)); }
return [{ json: { post_text: text } }];

const change = $json.incoming_text;
const prompt = 'Edit the attached image as follows: "' + change + '". Keep it professional, minimal, '
  + 'and suitable as a LinkedIn post image. Do not add any text overlays, logos or watermarks.';
return [{ json: { ...$json, edit_prompt: prompt } }];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');
return [{ json: { image_base64: base64 } }];

const res = $json;
const parts = res.candidates?.[0]?.content?.parts || [];
const imgPart = parts.find(p => p.inlineData || p.inline_data);
const inline = imgPart ? (imgPart.inlineData || imgPart.inline_data) : null;
if (!inline) { throw new Error('Gemini did not return image data: ' + JSON.stringify(res)); }
return [{ json: { image_base64: inline.data, mime_type: inline.mimeType || inline.mime_type || 'image/png' } }];

